#include <stdio.h>

#define M 19
#define P 19

int main(void) {
    int ht[M];
    int i, kk, h0, c, ok, jj, d;
    int keys[] = {47, 7, 29, 11, 16, 92, 22, 8, 3};
    int k = (int)(sizeof(keys) / sizeof(keys[0]));
    int total = 0;
    double asl;
    for (i = 0; i < M; i++) ht[i] = -1;
    for (kk = 0; kk < k; kk++) {
        h0 = keys[kk] % P;
        c = 1; ok = 0; jj = -1;
        for (d = 0; d < M; d++) {
            int idx = (h0 + d * d) % M;
            if (ht[idx] == -1) { ht[idx] = keys[kk]; ok = 1; jj = idx; break; }
            c++;
        }
        total += c;
        printf("插入 %2d: h0=%2d  探测%d次  落位 %2d\n", keys[kk], h0, c, jj);
    }
    asl = (double)total / (double)k;
    printf("二次探测 表长M=%d(=4k+3素数) 装填因子=%.3f 平均插入探测=%.3f\n", M, (double)k / (double)M, asl);
    return 0;
}
